let commentDepth = ref 0;  (* Current comment nesting *)

(* Distinguish keywords from identifiers: *)

let keyword s =
    match s with
    | "else"      -> ELSE
    | "begin"     -> BEGIN        
    | "end"       -> END
    | "false"     -> CSTBOOL false
    | "if"        -> IF
    | "in"        -> IN
    | "let"       -> LET
    | "val"       -> VAL
    | "fun"       -> FUN
    | "fn"        -> FN
    | "and"       -> AND
    | "not"       -> NOT
    | "then"      -> THEN
    | "true"      -> CSTBOOL true
    | "print"     -> PRIM1 "print"
    | "nil"       -> NIL
    | "hd"        -> HEAD
    | "tl"        -> TAIL
    | "fst"       -> FST (* CHANGED | Exercise 13.2 *)
    | "snd"       -> SND
    | "isnil"     -> PRIM1 "isnil"
    | "try"       -> TRY
    | "with"      -> WITH
    | "raise"     -> RAISE
    | "exception" -> EXN        
    | _           -> NAME s

